// The English source catalog: every message of the converted areas, by key. English is also the fallback for a
// key a language hasn't translated yet. Messages use ICU-lite (./icu.ts): {name}, plural, select, <b>tags</b>.
//
// The build inlines each message where it's used (scripts/i18n-plugin.ts): `t("file.new")` becomes
// `t(12,"New diagram")` in whatever chunk calls it, so English costs nothing extra at startup and this file is
// never loaded as a whole. Other languages are compiled from src/i18n/locales/<code>.json into lazy chunks.
//
// Adding or changing a message: docs/I18N.md. Keep the vocabulary of docs/UX-PRINCIPLES.md. Changing the English of
// a translated key marks it stale everywhere (`pnpm i18n:check`); until it's translated again, the old translation
// stays.

